      return statusCode >= 500;
    }

    return false;
  }

  /// Exponential backoff: 2s, 4s, 8s based on attempt index.
  Future<void> _backoff(int attempt) {
    final delay = _baseDelay * (1 << attempt); // 2s, 4s, 8s
    return Future.delayed(delay);
