/// Exercise demonstration videos currently bundled with the Android app.
///
/// The backend assigns a predictable video path to every exercise, including
/// demonstrations that have not been produced yet. Keeping this manifest
/// prevents those future paths from being presented as playable assets.
const Set<String> bundledExerciseVideos = {
  'assets/videos/barbell_back_squat.mp4',
  'assets/videos/barbell_bent_over_row.mp4',
  'assets/videos/barbell_curl.mp4',
  'assets/videos/barbell_deadlift.mp4',
  'assets/videos/bodyweight_squat.mp4',
  'assets/videos/broad_jump.mp4',
  'assets/videos/burpee.mp4',
  'assets/videos/chin_up.mp4',
  'assets/videos/dumbbell_bicep_curl.mp4',
  'assets/videos/dumbbell_overhead_press.mp4',
  'assets/videos/dumbbell_overhead_tricep_extension.mp4',
  'assets/videos/dumbbell_romanian_deadlift.mp4',
  'assets/videos/dumbbell_single_arm_row.mp4',
  'assets/videos/hanging_leg_raise.mp4',
  'assets/videos/high_knees.mp4',
  'assets/videos/jumping_jack.mp4',
  'assets/videos/leg_press.mp4',
  'assets/videos/mountain_climber.mp4',
  'assets/videos/plank.mp4',
  'assets/videos/pull_up.mp4',
  'assets/videos/push_up.mp4',
  'assets/videos/tricep_dips.mp4',
  'assets/videos/walking_lunge.mp4',
};

const Map<String, String> _exerciseVideoAliases = {
  // The curated exercise is named "Tricep Dip", while the supplied file uses
  // the commonly used plural filename.
  'assets/videos/tricep_dip.mp4': 'assets/videos/tricep_dips.mp4',
};

String? resolvedBundledExerciseVideoPath(String? path) {
  final normalized = path?.trim();
  if (normalized == null || normalized.isEmpty) return null;
  final resolved = _exerciseVideoAliases[normalized] ?? normalized;
  return bundledExerciseVideos.contains(resolved) ? resolved : null;
}

bool isBundledExerciseVideo(String? path) {
  return resolvedBundledExerciseVideoPath(path) != null;
}

import 'package:flutter/material.dart';
import 'package:video_player/video_player.dart';

import '../../core/theme/app_spacing.dart';
import 'exercise_video_catalog.dart';

const Set<String> _playableVideoExtensions = {
  'mp4',
  'm4v',
  'webm',
  'mkv',
  '3gp',
  'ts',
};

const Set<String> _playableUriSchemes = {'http', 'https'};

/// Returns whether [videoPath] has a video format supported by the client.
bool hasPlayableExerciseVideo(String? videoPath) {
  final trimmed = videoPath?.trim() ?? '';
  if (trimmed.isEmpty) return false;

  final uri = Uri.tryParse(trimmed);
  String candidate = trimmed;
  if (uri != null && uri.hasScheme) {
    if (!_playableUriSchemes.contains(uri.scheme.toLowerCase())) return false;
    if (uri.pathSegments.isEmpty) return false;
    candidate = uri.pathSegments.last;
  }

  final dotIndex = candidate.lastIndexOf('.');
  if (dotIndex < 0 || dotIndex == candidate.length - 1) return false;
  return _playableVideoExtensions
      .contains(candidate.substring(dotIndex + 1).toLowerCase());
}

bool _isNetworkVideo(String path) {
  final uri = Uri.tryParse(path);
  return uri != null &&
      uri.hasScheme &&
      _playableUriSchemes.contains(uri.scheme.toLowerCase());
}

bool _isAvailableVideo(String? path) {
  final value = path?.trim() ?? '';
  if (!hasPlayableExerciseVideo(value)) return false;
  return _isNetworkVideo(value) || isBundledExerciseVideo(value);
}

/// Plays an exercise demonstration on demand, or shows an honest fallback
/// while that exercise's demonstration is not yet bundled.
class ExerciseMedia extends StatefulWidget {
  const ExerciseMedia({
    super.key,
    required this.videoPath,
    this.exerciseName,
    this.borderRadius = 16,
  });

  final String? videoPath;
  final String? exerciseName;
  final double borderRadius;

  @override
  State<ExerciseMedia> createState() => _ExerciseMediaState();
}

class _ExerciseMediaState extends State<ExerciseMedia> {
  VideoPlayerController? _controller;
  bool _isLoading = false;
  String? _error;

  bool get _hasVideo => _isAvailableVideo(widget.videoPath);

  @override
  void didUpdateWidget(covariant ExerciseMedia oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.videoPath != widget.videoPath) {
      _disposeController();
      _error = null;
      _isLoading = false;
    }
  }

  Future<void> _openVideo() async {
    final path = widget.videoPath?.trim();
    if (path == null || !_hasVideo || _isLoading) return;

    setState(() {
      _isLoading = true;
      _error = null;
    });

    final playablePath = _isNetworkVideo(path)
        ? path
        : resolvedBundledExerciseVideoPath(path) ?? path;
    final controller = _isNetworkVideo(playablePath)
        ? VideoPlayerController.networkUrl(Uri.parse(playablePath))
        : VideoPlayerController.asset(playablePath);

    try {
      await controller.initialize();
      await controller.setLooping(true);
      await controller.setVolume(0);
      await controller.play();
      if (!mounted) {
        await controller.dispose();
        return;
      }
      setState(() {
        _controller = controller;
        _isLoading = false;
      });
    } catch (_) {
      await controller.dispose();
      if (!mounted) return;
      setState(() {
        _isLoading = false;
        _error = 'Video could not be opened';
      });
    }
  }

  Future<void> _togglePlayback() async {
    final controller = _controller;
    if (controller == null) return;
    controller.value.isPlaying
        ? await controller.pause()
        : await controller.play();
    if (mounted) setState(() {});
  }

  void _disposeController() {
    final controller = _controller;
    _controller = null;
    controller?.dispose();
  }

  @override
  void dispose() {
    _disposeController();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final controller = _controller;
    final semanticsBase =
        _hasVideo ? 'Exercise video available' : 'No video available';
    final semanticsLabel = widget.exerciseName == null
        ? semanticsBase
        : '$semanticsBase for ${widget.exerciseName}';

    return Semantics(
      label: semanticsLabel,
      container: true,
      explicitChildNodes: true,
      button: _hasVideo && controller == null,
      child: AspectRatio(
        key: const Key('exercise-media'),
        aspectRatio: 16 / 9,
        child: ClipRRect(
          borderRadius: BorderRadius.circular(widget.borderRadius),
          child: ColoredBox(
            color: theme.colorScheme.surfaceContainerHighest,
            child: controller != null && controller.value.isInitialized
                ? _VideoPlayback(
                    controller: controller,
                    onTogglePlayback: _togglePlayback,
                  )
                : _VideoPrompt(
                    hasVideo: _hasVideo,
                    isLoading: _isLoading,
                    error: _error,
                    onPressed: _openVideo,
                  ),
          ),
        ),
      ),
    );
  }
}

class _VideoPrompt extends StatelessWidget {
  const _VideoPrompt({
    required this.hasVideo,
    required this.isLoading,
    required this.error,
    required this.onPressed,
  });

  final bool hasVideo;
  final bool isLoading;
  final String? error;
  final VoidCallback onPressed;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    if (isLoading) return const Center(child: CircularProgressIndicator());

    final canOpen = hasVideo;
    final label =
        error ?? (canOpen ? 'Play video guide' : 'No video available');
    final icon = error != null
        ? Icons.refresh
        : canOpen
            ? Icons.play_circle_outline
            : Icons.videocam_off_outlined;

    return InkWell(
      onTap: canOpen ? onPressed : null,
      child: Center(
        child: Padding(
          padding: const EdgeInsets.all(AppSpacing.md),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(icon, size: 48, color: theme.colorScheme.onSurfaceVariant),
              const SizedBox(height: AppSpacing.sm),
              Text(
                label,
                textAlign: TextAlign.center,
                style: theme.textTheme.bodyMedium?.copyWith(
                  color: theme.colorScheme.onSurfaceVariant,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _VideoPlayback extends StatelessWidget {
  const _VideoPlayback({
    required this.controller,
    required this.onTogglePlayback,
  });

  final VideoPlayerController controller;
  final VoidCallback onTogglePlayback;

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Expanded(
          child: Stack(
            fit: StackFit.expand,
            children: [
              ColoredBox(
                color: Colors.black,
                child: FittedBox(
                  fit: BoxFit.contain,
                  child: SizedBox(
                    width: controller.value.size.width,
                    height: controller.value.size.height,
                    child: VideoPlayer(controller),
                  ),
                ),
              ),
              const Positioned(
                top: AppSpacing.sm,
                right: AppSpacing.sm,
                child: Tooltip(
                  message: 'Video is muted',
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      color: Colors.black54,
                      shape: BoxShape.circle,
                    ),
                    child: Padding(
                      padding: EdgeInsets.all(AppSpacing.xs),
                      child: Icon(
                        Icons.volume_off,
                        size: 18,
                        color: Colors.white,
                      ),
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
        ColoredBox(
          color: Colors.black87,
          child: Row(
            children: [
              IconButton(
                tooltip:
                    controller.value.isPlaying ? 'Pause video' : 'Play video',
                onPressed: onTogglePlayback,
                color: Colors.white,
                icon: Icon(controller.value.isPlaying
                    ? Icons.pause
                    : Icons.play_arrow),
              ),
              Expanded(
                child: VideoProgressIndicator(
                  controller,
                  allowScrubbing: true,
                  padding: const EdgeInsets.symmetric(vertical: 20),
                ),
              ),
              const SizedBox(width: AppSpacing.sm),
            ],
          ),
        ),
      ],
    );
  }
}
